  }
  for(int i=0;i<8;i++){int t=sq+knight_d[i]; if(!OFF(t)&&board[t]==PC(by,KNIGHT)) return 1;}
  for(int i=0;i<8;i++){int t=sq+king_d[i]; if(!OFF(t)&&board[t]==PC(by,KING)) return 1;}
  for(int i=0;i<4;i++){int t=sq+bishop_d[i]; while(!OFF(t)){p=board[t]; if(p){ if(COL(p)==by&&(TYP(p)==BISHOP||TYP(p)==QUEEN)) return 1; break;} t+=bishop_d[i];}}
