  board[from]=EMPTY; hash^=zob[p][from];
  int np= promo?PC(us,promo):p;
  board[to]=np; hash^=zob[np][to];
  if(fl&F_CASTLE){ int rf,rt; if(to>from){rf=to+1;rt=to-1;} else {rf=to-2;rt=to+1;} int r=board[rf]; board[rf]=EMPTY; board[rt]=r; hash^=zob[r][rf]^zob[r][rt]; }
  if(TYP(p)==KING) ksq[us]=to;
  hash^=zob_castle[castle]; castle&=castle_mask[from]&castle_mask[to]; hash^=zob_castle[castle];
  if(ep>=0) hash^=zob_ep[FL(ep)];
  ep=(fl&F_DPUSH)?(from+to)/2:-1;
  if(ep>=0) hash^=zob_ep[FL(ep)];
