/* ---------- evaluation ---------- */
static int evaluate(){
  int mg[2]={0,0}, eg[2]={0,0}, phase=0;
  int npawns[2]={0,0}, nonpawn_mat[2]={0,0}, bishops[2]={0,0};
  int pawns[2][8]; // per file pawn squares list count (for passed detection use board scan)
  (void)pawns;
  for(int sq=0;sq<128;sq++){
    if(OFF(sq)){ sq+=7; continue; }
    int p=board[sq]; if(!p) continue;
    int c=COL(p), t=TYP(p), s=S64(sq);
    mg[c]+=mg_tab[c][t][s]; eg[c]+=eg_tab[c][t][s]; phase+=phase_val[t];
    if(t==PAWN){
      npawns[c]++;
      // passed pawn check
      int fwd= c==WHITE?16:-16; int passed=1;
      for(int q=sq+fwd; !OFF(q)&&passed; q+=fwd){
        for(int d=-1; d<=1; d++){ int z=q+d; if(!OFF(z)&&board[z]==PC(c^1,PAWN)){ passed=0; break; } }
      }
      if(passed){ int r= c==WHITE?RK(sq):7-RK(sq); mg[c]+=6*r; eg[c]+=8+r*r*6; }
      // doubled
      int ahead=sq+fwd; if(!OFF(ahead)&&board[ahead]==p){ mg[c]-=8; eg[c]-=15; }
      // isolated
      int iso=1; for(int q=FL(sq)-1;q<=FL(sq)+1;q+=2){ if(q<0||q>7) continue; for(int r=1;r<7;r++){ if(board[r*16+q]==p){ iso=0; break; } } if(!iso) break; }
      if(iso){ mg[c]-=10; eg[c]-=12; }
    } else if(t!=KING){ nonpawn_mat[c]+=mg_val[t]; if(t==BISHOP) bishops[c]++; }
  }
  for(int c=0;c<2;c++) if(bishops[c]>=2){ mg[c]+=25; eg[c]+=45; }
  // insufficient material / drawish scaling
  int us=side, them=side^1;
  if(phase>24) phase=24;
  int mgs=mg[us]-mg[them], egs=eg[us]-eg[them];
  int score=(mgs*phase+egs*(24-phase))/24;
  // scale down when the leading side has no pawns and little material
  int lead= score>0?us:them;
  if(npawns[lead]==0 && nonpawn_mat[lead]<=mg_val[BISHOP]) score=score/16;
  else if(npawns[lead]==0 && nonpawn_mat[lead]<=2*mg_val[KNIGHT]) score=score/4;
  return score;
}

