static void score_moves(int *moves,int *scores,int n,int tt_move){
  for(int i=0;i<n;i++){
    int m=moves[i];
    if(m==tt_move){ scores[i]=1<<30; continue; }
    int fl=MV_FLAGS(m), pr=MV_PROMO(m);
    if(fl&F_CAP){
      int victim= (fl&F_EP)?PAWN:TYP(board[MV_TO(m)]);
      int att=TYP(board[MV_FROM(m)]);
      scores[i]=(1<<20)+victim*100-att+(pr==QUEEN?500:0);
    } else if(pr){ scores[i]=(1<<20)+(pr==QUEEN?400:-100); }
    else if(m==killers[ply][0]) scores[i]=(1<<19);
