  }
}
static int pick(int *moves,int *scores,int n,int i){
  int b=i; for(int j=i+1;j<n;j++) if(scores[j]>scores[b]) b=j;
  int tm=moves[i],ts=scores[i]; moves[i]=moves[b]; scores[i]=scores[b]; moves[b]=tm; scores[b]=ts; return moves[i];
}

static int quiesce(int alpha,int beta){
  nodes++;
  if((nodes&2047)==0) check_time();
  if(stop_search) return 0;
  if(ply>=MAXPLY-1) return evaluate();
  int stand=evaluate();
  if(stand>=beta) return stand;
  if(stand>alpha) alpha=stand;
  int moves[256],scores[256]; int n=gen_moves(moves,1); score_moves(moves,scores,n,0);
  int best=stand;
  for(int i=0;i<n;i++){
    int m=pick(moves,scores,n,i);
    if(!MV_PROMO(m)){
      int victim=(MV_FLAGS(m)&F_EP)?PAWN:TYP(board[MV_TO(m)]);
      if(stand+mg_val[victim]+150<alpha) continue;
    }
    if(!make_move(m)) continue;
    int s=-quiesce(-beta,-alpha);
    unmake_move();
    if(stop_search) return 0;
    if(s>best){ best=s; if(s>alpha){ alpha=s; if(s>=beta) return s; } }
  }
  return best;
}

static int search(int alpha,int beta,int depth,int do_null){
  if((nodes&2047)==0) check_time();
  if(stop_search) return 0;
