    if(is_repetition()||halfmove>=100) return draw_score();
    if(alpha<-MATE+ply) alpha=-MATE+ply;
    if(beta>MATE-ply-1) beta=MATE-ply-1;
    if(alpha>=beta) return alpha;
    if(ply>=MAXPLY-1) return evaluate();
  }
  int in_check=attacked(ksq[side],side^1);
  if(in_check) depth++;
  if(depth<=0) return quiesce(alpha,beta);
  nodes++;
  TTE *e=&tt[hash&(TT_SIZE-1)]; int tt_move=0;
  if(e->key==hash){
    tt_move=e->move;
    if(!root&&e->depth>=depth){
      int s=e->score; if(s>MATE-1000) s-=ply; else if(s<-MATE+1000) s+=ply;
      if(e->flag==TT_EXACT) return s;
      if(e->flag==TT_LOWER&&s>=beta) return s;
      if(e->flag==TT_UPPER&&s<=alpha) return s;
    }
  }
  int pv_node= beta-alpha>1;
  int static_eval=evaluate();
  if(!pv_node&&!in_check&&depth<=3&&static_eval-120*depth>=beta) return static_eval;
  if(!pv_node&&do_null&&!in_check&&depth>=3&&static_eval>=beta&&has_non_pawn(side)){
    make_null(); int R=2+depth/6; int s=-search(-beta,-beta+1,depth-1-R,0); unmake_null();
    if(stop_search) return 0;
    if(s>=beta){ if(s>MATE-1000) s=beta; return s; }
  }
  int moves[256],scores[256]; int n=gen_moves(moves,0); score_moves(moves,scores,n,tt_move);
  int best=-INF,best_move=0,legal=0,flag=TT_UPPER;
  for(int i=0;i<n;i++){
    int m=pick(moves,scores,n,i);
    if(!make_move(m)) continue;
    legal++;
    int is_cap=MV_FLAGS(m)&F_CAP, is_promo=MV_PROMO(m);
    int gives_check=attacked(ksq[side],side^1);
    if(!pv_node&&!in_check&&!is_cap&&!is_promo&&!gives_check&&depth<=2&&legal>1&&static_eval+150*depth<=alpha){ unmake_move(); continue; }
    int s;
    if(legal==1) s=-search(-beta,-alpha,depth-1,1);
    else {
      int r=0;
      if(depth>=3&&legal>3&&!is_cap&&!is_promo&&!in_check&&!gives_check){ r=1+(legal>8)+(depth>6&&!pv_node); if(r>depth-2) r=depth-2; if(r<0) r=0; }
      s=-search(-alpha-1,-alpha,depth-1-r,1);
      if(s>alpha&&r>0) s=-search(-alpha-1,-alpha,depth-1,1);
      if(s>alpha&&s<beta) s=-search(-beta,-alpha,depth-1,1);
    }
    unmake_move();
    if(stop_search) return 0;
    if(s>best){
      best=s; best_move=m;
      if(s>alpha){
        alpha=s; flag=TT_EXACT;
        if(root) root_best=m;
        pv_tab[ply][ply]=m; for(int k=ply+1;k<pv_len[ply+1];k++) pv_tab[ply][k]=pv_tab[ply+1][k]; pv_len[ply]=pv_len[ply+1];
        if(s>=beta){
          flag=TT_LOWER;
          if(!is_cap){ if(killers[ply][0]!=m){ killers[ply][1]=killers[ply][0]; killers[ply][0]=m; } history_h[side][MV_FROM(m)][MV_TO(m)]+=depth*depth; }
          break;
        }
      }
    }
  }
  if(!legal) return in_check?-MATE+ply:draw_score();
  int ss=best; if(ss>MATE-1000) ss+=ply; else if(ss<-MATE+1000) ss-=ply;
  if(e->key!=hash||depth>=e->depth||flag==TT_EXACT){ e->key=hash; e->move=best_move; e->score=ss; e->depth=depth; e->flag=flag; }
  return best;
}

static void sq_str(int sq,char *s){ s[0]='a'+FL(sq); s[1]='1'+RK(sq); s[2]=0; }
static void move_str(int m,char *s){
  sq_str(MV_FROM(m),s); sq_str(MV_TO(m),s+2);
  if(MV_PROMO(m)){ s[4]="  nbrq"[MV_PROMO(m)]; s[5]=0; } else s[4]=0;
}
static int parse_move(const char *s){
  int from=(s[0]-'a')+(s[1]-'1')*16, to=(s[2]-'a')+(s[3]-'1')*16; int promo=0;
  if(s[4]&&s[4]!=' '&&s[4]!='\n'){ switch(s[4]){case 'n':promo=KNIGHT;break;case 'b':promo=BISHOP;break;case 'r':promo=ROOK;break;case 'q':promo=QUEEN;break;} }
  int moves[256]; int n=gen_moves(moves,0);
  for(int i=0;i<n;i++) if(MV_FROM(moves[i])==from&&MV_TO(moves[i])==to&&MV_PROMO(moves[i])==promo) return moves[i];
  return 0;
}

static void think(double ms,int maxdepth){
  gettimeofday(&t_start,NULL); time_limit=ms; stop_search=0; nodes=0; root_best=0;
  memset(killers,0,sizeof(killers)); memset(history_h,0,sizeof(history_h));
  int moves[256]; int n=gen_moves(moves,0); int legal=0, only=0;
  for(int i=0;i<n;i++){ if(make_move(moves[i])){ legal++; only=moves[i]; unmake_move(); } }
  if(legal==0){ printf("bestmove 0000\n"); fflush(stdout); return; }
  if(legal==1){ char s[8]; move_str(only,s); printf("bestmove %s\n",s); fflush(stdout); return; }
  int best=only, score=0;
  for(int d=1; d<=maxdepth; d++){
    ply=0; undo_top=0;
    int s=search(-INF,INF,d,1);
    if(stop_search){ if(root_best) best=root_best; break; }
    score=s; best=root_best?root_best:best;
    char pv[1024]; pv[0]=0; for(int k=0;k<pv_len[0];k++){ char ms[8]; move_str(pv_tab[0][k],ms); strcat(pv,ms); strcat(pv," "); }
    printf("info depth %d score cp %d nodes %ld time %d pv %s\n",d,score,nodes,(int)now_ms(),pv); fflush(stdout);
    if(score>MATE-1000||score<-MATE+1000) break;
    if(time_limit>0 && now_ms()>time_limit*0.55) break;
  }
  char s[8]; move_str(best,s); printf("bestmove %s\n",s); fflush(stdout);
}

static void set_startpos(){
  for(int i=0;i<128;i++) board[i]=EMPTY;
  int back[8]={ROOK,KNIGHT,BISHOP,QUEEN,KING,BISHOP,KNIGHT,ROOK};
  for(int f=0;f<8;f++){ board[f]=PC(WHITE,back[f]); board[0x10+f]=PC(WHITE,PAWN); board[0x60+f]=PC(BLACK,PAWN); board[0x70+f]=PC(BLACK,back[f]); }
  side=WHITE; castle=15; ep=-1; halfmove=0; ksq[WHITE]=0x04; ksq[BLACK]=0x74;
  hash=compute_hash(); game_len=0; ply=0; undo_top=0; hist[0]=hash;
}
static void set_fen(const char *fen){
  for(int i=0;i<128;i++) board[i]=EMPTY;
  int r=7,f=0; const char *p=fen;
  while(*p&&*p!=' '){
    if(*p=='/'){ r--; f=0; } else if(*p>='1'&&*p<='8'){ f+=*p-'0'; } else {
      int c= (*p>='a')?BLACK:WHITE; char ch=(*p>='a')?*p-32:*p; int t=0;
      switch(ch){case 'P':t=PAWN;break;case 'N':t=KNIGHT;break;case 'B':t=BISHOP;break;case 'R':t=ROOK;break;case 'Q':t=QUEEN;break;case 'K':t=KING;break;}
      board[r*16+f]=PC(c,t); if(t==KING) ksq[c]=r*16+f; f++;
    }
    p++;
  }
  while(*p==' ') p++;
  side= *p=='b'?BLACK:WHITE; while(*p&&*p!=' ') p++; while(*p==' ') p++;
  castle=0; while(*p&&*p!=' '){ if(*p=='K') castle|=1; if(*p=='Q') castle|=2; if(*p=='k') castle|=4; if(*p=='q') castle|=8; p++; } while(*p==' ') p++;
  ep=-1; if(*p&&*p!='-'){ ep=(p[0]-'a')+(p[1]-'1')*16; } while(*p&&*p!=' ') p++; while(*p==' ') p++;
  halfmove=0; if(*p) halfmove=atoi(p);
  hash=compute_hash(); game_len=0; ply=0; undo_top=0; hist[0]=hash;
}
static void apply_game_move(const char *s){
  int m=parse_move(s); if(!m){ fprintf(stderr,"bad move %s\n",s); return; }
  ply=0; undo_top=0; make_move(m); ply=0; undo_top=0; game_len++; hist[game_len]=hash;
}
static long perft(int depth){
  if(depth==0) return 1;
  int moves[256]; int n=gen_moves(moves,0); long c=0;
  for(int i=0;i<n;i++){ if(!make_move(moves[i])) continue; c+=perft(depth-1); unmake_move(); }
  return c;
}

